uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// 2D Value Noise for organic tree evolution
float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Evaluates Upward Tree Connections
void evalTreeConn(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float nodeGrowth, inout float minDistLine, inout float activePulse, inout float lineAlpha) {
    vec2 cellId = id + offs;
    vec2 neighborId = cellId + dir;

    // 1. Organic Pruning: Randomly drop ~35% of branches to create a tree structure
    if(hash21(cellId + dir * 1.33) > 0.65) return;

    // 2. Check if the target neighbor is "alive" in the evolution noise
    float horizontalBias = exp(-abs(neighborId.x) * 0.12); // Centers the tree
    float nNeighbor = vnoise(neighborId * 0.15 + vec2(0.0, t * 0.15));
    float neighborGrowth = smoothstep(0.4, 0.65, nNeighbor * horizontalBias);

    // Only draw the connection if the neighbor branch is growing
    if(neighborGrowth > 0.0) {
        vec2 p2 = offs + dir + 0.5 + 0.3 * sin(t * 1.5 + hash22(neighborId) * 6.28);

        float dLine = distLine(f, p1, p2);

        if (dLine < minDistLine) {
            minDistLine = dLine;

            // The line smoothly fades in only if BOTH connecting nodes are alive
            lineAlpha = min(nodeGrowth, neighborGrowth); 

            // 3. Upward Data Flow: Pulses ride up the Y-axis of the grid
            float worldY = neighborId.y;
            float pulse = smoothstep(0.8, 1.0, sin(worldY * 0.8 - t * 6.0));
            activePulse = pulse;
        }
    }
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Interactive Mouse Pan
    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    // 2. Timing & Parameters
    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float t = iTime * spd;

    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = (u_layers <= 0.0) ? 4.0 : u_layers;
    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity * 3.0;

    // Colors
    float hueBase = fract(0.55 + u_color_base + (t * u_color_cycle * 0.1));
    float huePulse = fract(0.10 + u_color_pulse + (t * u_color_cycle * 0.1));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.6, 1.0)); // Clean, corporate vector saturation
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // --- Clean Gradient Background ---
    vec3 bgCenter = baseCol * 0.12; 
    vec3 bgEdge = vec3(0.015, 0.02, 0.03);
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.2);

    // 3. Layer Loop for Crisp Alpha Parallax
    for(int i = 0; i < 4; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Depth (Fixed layers instead of zooming)
        float z = fi / 3.0; // 0.0 to 1.0
        float fade = mix(0.15, 1.0, z); // Foreground is fully opaque, background is ghosted

        float size = mix(18.0, 5.0, z) * scaleBase * density;
        vec2 layerUV = uv * size;

        // Tree growth direction (Scrolling downwards makes the tree grow upwards)
        layerUV.y -= t * (3.0 + z * 2.0);
        layerUV.x += mouseOffset.x * size * (1.0 - z * 0.5); // Parallax pan

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        float minDistNode = 100.0;
        float minDistLine = 100.0;
        float activePulse = 0.0;
        float activeNodeAlpha = 0.0;
        float activeLineAlpha = 0.0;

        // 3x3 Neighborhood Loop
        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 cellId = id + offs;

                // Evolution noise mask
                // Focuses the growth in the center (trunk) and fades out at the edges
                float hBias = exp(-abs(cellId.x) * 0.12); 
                float n = vnoise(cellId * 0.15 + vec2(0.0, t * 0.15));
                float nodeGrowth = smoothstep(0.4, 0.65, n * hBias);

                // Only process if the node is actively growing
                if(nodeGrowth > 0.0) {
                    vec2 p1 = offs + 0.5 + 0.3 * sin(t * 1.5 + hash22(cellId) * 6.28);

                    // Track closest node
                    float dNode = length(f - p1);
                    if(dNode < minDistNode) {
                        minDistNode = dNode;
                        activeNodeAlpha = nodeGrowth;
                    }

                    // Forward-looking connections (ONLY UPWARDS)
                    evalTreeConn(f, p1, offs, vec2(-1.0, 1.0), id, t, nodeGrowth, minDistLine, activePulse, activeLineAlpha); // Top-Left
                    evalTreeConn(f, p1, offs, vec2(0.0, 1.0), id, t, nodeGrowth, minDistLine, activePulse, activeLineAlpha);  // Top-Center
                    evalTreeConn(f, p1, offs, vec2(1.0, 1.0), id, t, nodeGrowth, minDistLine, activePulse, activeLineAlpha);  // Top-Right
                }
            }
        }

        // --- Crisp SDF Rendering ---
        float px = 0.015; // Anti-aliasing fringe

        // Draw crisp lines multiplied by their growth alpha
        float lineThickness = 0.012;
        float lineShape = smoothstep(lineThickness + px, lineThickness, minDistLine) * activeLineAlpha;

        // Draw crisp "Atom" nodes multiplied by their growth alpha
        float nRad = 0.06;
        float nodeRing = smoothstep(nRad + px, nRad, minDistNode) - smoothstep(nRad*0.6 + px, nRad*0.6, minDistNode);
        float nodeCore = smoothstep(nRad*0.3 + px, nRad*0.3, minDistNode);
        float nodeShape = clamp(nodeRing + nodeCore, 0.0, 1.0) * activeNodeAlpha;

        // --- Layer Compositing (Alpha Blending) ---
        vec4 layerData = vec4(0.0);

        // 1. Color the lines
        vec3 lineColor = mix(baseCol, pulseCol, activePulse * pulseInt);
        layerData.rgb = lineColor;
        layerData.a = lineShape;

        // 2. Color the nodes (Pure white atoms drawn OVER the lines)
        layerData.rgb = mix(layerData.rgb, vec3(1.0), nodeShape);
        layerData.a = max(layerData.a, nodeShape);

        // 3. Apply Depth Alpha
        layerData.a *= fade * 0.9; 

        // Blend Layer onto the final image
        finalColor = mix(finalColor, layerData.rgb, layerData.a);
    }

    // 4. Subtle UI Vignette
    float vig = 1.0 - length(uv0) * 0.45;
    finalColor *= smoothstep(0.1, 1.0, vig);

    fragColor = vec4(finalColor, 1.0);
}
